describe('Test Cases Listing', () => {
  it('should display the list of test cases', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('a[href="#collapse1"]').should('be.visible');
    cy.get('a[href="#collapse2"]').should('be.visible');
    cy.get('a[href="#collapse3"]').should('be.visible');
    cy.get('a[href="#collapse4"]').should('be.visible');
    cy.get('a[href="#collapse5"]').should('be.visible');
    cy.get('a[href="#collapse6"]').should('be.visible');
    cy.get('a[href="#collapse7"]').should('be.visible');
    cy.get('a[href="#collapse8"]').should('be.visible');
    cy.get('a[href="#collapse9"]').should('be.visible');
    cy.get('a[href="#collapse10"]').should('be.visible');
    cy.get('a[href="#collapse11"]').should('be.visible');
    cy.get('a[href="#collapse12"]').should('be.visible');
    cy.get('a[href="#collapse13"]').should('be.visible');
    cy.get('a[href="#collapse14"]').should('be.visible');
    cy.get('a[href="#collapse15"]').should('be.visible');
    cy.get('a[href="#collapse16"]').should('be.visible');
  });
  it('should not change the URL when clicking a test case link and collapsing it', () => {
    cy.visit('https://automationexercise.com/test_cases');
    cy.get('a[href="#collapse1"]').click();
    cy.url().should('eq', 'https://automationexercise.com/test_cases');
    cy.get('a[href="#collapse1"]').click();
    cy.url().should('eq', 'https://automationexercise.com/test_cases');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Test Cases Listing', () => {
  test('should display the list of test cases', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await expect(page.locator('a[href="#collapse1"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse2"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse3"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse4"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse5"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse6"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse7"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse8"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse9"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse10"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse11"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse12"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse13"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse14"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse15"]')).toBeVisible();
    await expect(page.locator('a[href="#collapse16"]')).toBeVisible();
  });
  test('should not change the URL when clicking a test case link and collapsing it', async ({ page }) => {
    await page.goto('https://automationexercise.com/test_cases');
    await page.click('a[href="#collapse1"]');
    await expect(page).toHaveURL('https://automationexercise.com/test_cases');
    await page.click('a[href="#collapse1"]');
    await expect(page).toHaveURL('https://automationexercise.com/test_cases');
  });
});
